// 把并列数组拆成逐条商品 + 解析价格数字
const out = [];
for (const item of $input.all()) {
  const d = item.json;
  const n = (d.title||[]).length;
  for (let i=0;i<n;i++){
    const priceStr = (d.price&&d.price[i]||'').replace(/[^0-9]/g,'');
    out.push({ json: {
      title: d.title[i]||'',
      buy_price_jpy: parseInt(priceStr||'0',10),
      url: d.url&&d.url[i]||'',
      image: d.image&&d.image[i]||''
    }});
  }
}
return out;

// === 评分引擎 (核心IP) ===
const FX = 155;           // 美元兑日元, 校准用
const items = $input.all();
const kb = $('读需求知识库').all().map(x=>x.json);
const demandWeight = {S:1.0, A:0.7, B:0.4};
const shipCost = {light:2500, med:6000, heavy:15000};
const riskPenalty = {light:0, med:10, heavy:30};
const out = [];
for (const it of items){
  const d = it.json;
  const t = (d.title||'').toLowerCase();
  // 用 jp_name / hot_models 关键词匹配 KB 行
  const row = kb.find(r => {
    const keys = ((r.jp_name||'')+' '+(r.hot_models||'')).toLowerCase().split(/[\s,]+/).filter(Boolean);
    return keys.some(k => k.length>1 && t.includes(k));
  });
  if(!row){ continue; } // 不在知识库 = 不关心
  const resaleMid = (Number(row.resale_usd_low)+Number(row.resale_usd_high))/2;
  const ship = shipCost[row.ship_class]||6000;
  const fees = Math.round(d.buy_price_jpy*0.1)+500;
  const cost = d.buy_price_jpy + ship + fees;
  const revenue = resaleMid * FX;
  const profit = Math.round(revenue - cost);
  const margin = cost>0 ? profit/cost : 0;
  let score = margin*100*(demandWeight[row.demand_tier]||0.4) - (riskPenalty[row.ship_class]||10) - (row.voltage_relevant==='yes'?15:0);
  // 成色加权
  if(/ジャンク|不動|故障|部品取り|まとめ/.test(d.title)) score += 8;
  if(/動作未確認/.test(d.title)) score += 4;
  const alert = margin>=0.6 && profit>=8000 && (row.demand_tier==='S'||row.demand_tier==='A');
  out.push({ json: { ...d,
    brand: row.brand, category: row.category, model: row.hot_models,
    demand_tier: row.demand_tier, profit_jpy: profit,
    margin_pct: Math.round(margin*100), deal_score: Math.round(score),
    harvest_parts: row.category, selling_points: row.notes,
    hot: score>=80, alert
  }});
}
return out;

